from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class BbcapParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        if execution_config['release'] >= 22.3 and execution_config['is_fsm6']:
            self.set_parameter('smodBoardConfigType', 'Auto')
            self.set_parameter('bbCardUsage', 2)
